var fsBtnMap = {
    byScience: "stdDashBtnFsByScience",
    byCourse: "stdDashBtnFsByCourse",
    byClass: "stdDashBtnFsByClass",
    trend: "stdDashBtnFsTrend",
    ratio: "stdDashBtnFsRatio",
    overview: "stdDashBtnFsOverview"
};

function resetFullscreenButtons() {
    var key;
    for (key in fsBtnMap) {
        if (fsBtnMap.hasOwnProperty(key)) {
            var btn = getEl(fsBtnMap[key]);
            if (btn) {
                btn.classList.add("std-dash-fs-btn-inactive");
                btn.setAttribute("aria-disabled", "true");
            }
        }
    }
}

function registerFullscreen(key, title, optionsBuilder, layoutMode) {
    fullscreenStates[key] = {
        title: title,
        optionsBuilder: optionsBuilder,
        layoutMode: layoutMode || "horizontal"
    };
    var btn = getEl(fsBtnMap[key]);
    if (btn) {
        btn.classList.remove("std-dash-fs-btn-inactive");
        btn.removeAttribute("aria-disabled");
    }
}

