input.new_string:
function openFullscreen(key) {
    var state = fullscreenStates[key];
    var overlay = getEl("stdDashFullscreenOverlay");
    var titleEl = getEl("stdDashFullscreenTitle");
    var chartWrap = getEl("stdDashFullscreenChartWrap");
    var options;
    if (!state || !overlay || !state.optionsBuilder) {
        return;
    }
    if (overlay.parentNode !== document.body) {
        document.body.appendChild(overlay);
    }
    if (titleEl) {
        titleEl.textContent = state.title || "Biểu đồ chi tiết";
    }
    options = state.optionsBuilder();
    if (chartWrap && options && options.chart) {
        chartWrap.style.height = options.chart.height + "px";
    }
    renderChart("#stdDashChartFullscreen", options, null);
    if (state.layoutMode === "line") {
        overlay.className = "std-dash-fullscreen std-dash-fullscreen-line";
    } else if (state.layoutMode === "center") {
        overlay.className = "std-dash-fullscreen std-dash-fullscreen-center";
    } else {
        overlay.className = "std-dash-fullscreen std-dash-fullscreen-horizontal";
    }
    document.body.style.overflow = "hidden";
    if (chartInstances["stdDashChartFullscreen"]) {
        chartInstances["stdDashChartFullscreen"].windowResizeHandler();
    }
}

function closeFullscreen() {
    var overlay = getEl("stdDashFullscreenOverlay");
    var chartWrap = getEl("stdDashFullscreenChartWrap");
    if (!overlay) {
        return;
    }
    overlay.className = "std-dash-fullscreen d-none";
    document.body.style.overflow = "";
    destroyChart("#stdDashChartFullscreen");
    if (chartWrap) {
        chartWrap.style.height = "";
    }
}

